package main

import (
	"fmt"
	"os"
	"strings"
)

type DateRec struct {
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var dateRec DateRec
var inputLines []string
var inputIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isLeap() bool {
	return WsLeapFlag == "Y"
}

func parsePic9(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	var v int64 = 0
	for i := 0; i < len(t); i++ {
		c := t[i]
		if c < '0' || c > '9' {
			return 0
		}
		v = v*10 + int64(c-'0')
	}
	return v
}

func formatPic9(v int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	r := v % mod
	if r < 0 {
		r += mod
	}
	return fmt.Sprintf("%0*d", width, r)
}

func splitLines(data []byte) []string {
	if len(data) == 0 {
		return nil
	}
	var lines []string
	start := 0
	for i, b := range data {
		if b == '\n' {
			line := string(data[start:i])
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			lines = append(lines, line)
			start = i + 1
		}
	}
	if start < len(data) {
		line := string(data[start:])
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		lines = append(lines, line)
	}
	return lines
}

func openInput() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = nil
			inputIdx = 0
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	inputLines = splitLines(data)
	inputIdx = 0
}

func MainPara() {
	openInput()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE DATE-FILE (no action needed)
	line := "VALID: " + formatPic9(WsValid, 2) + " BAD MONTH: " + formatPic9(WsBadMonth, 2) + " BAD DAY: " + formatPic9(WsBadDay, 2)
	os.Stdout.WriteString(line + "\n")
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	dateRec.DtId = line[0:4]
	dateRec.DtYyyy = parsePic9(line[4:8])
	dateRec.DtMm = parsePic9(line[8:10])
	dateRec.DtDd = parsePic9(line[10:12])
}

func ProcessPara() {
	LeapPara()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		line := dateRec.DtId + " BAD MONTH " + formatPic9(dateRec.DtMm, 2)
		os.Stdout.WriteString(line + "\n")
	} else {
		DaysPara()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			line := dateRec.DtId + " BAD DAY " + formatPic9(dateRec.DtDd, 2) + " MAX " + formatPic9(WsMaxDay, 2)
			os.Stdout.WriteString(line + "\n")
		} else {
			WsValid = (WsValid + 1) % 100
			line := dateRec.DtId + " VALID " + formatPic9(dateRec.DtYyyy, 4) + "-" + formatPic9(dateRec.DtMm, 2) + "-" + formatPic9(dateRec.DtDd, 2)
			os.Stdout.WriteString(line + "\n")
		}
	}
	ReadPara()
}

func LeapPara() {
	WsQ = (dateRec.DtYyyy / 4) % 10000
	WsR4 = dateRec.DtYyyy % 4
	WsQ = (dateRec.DtYyyy / 100) % 10000
	WsR100 = dateRec.DtYyyy % 100
	WsQ = (dateRec.DtYyyy / 400) % 10000
	WsR400 = dateRec.DtYyyy % 400
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	MainPara()
}
